"""User-only additions around the unchanged upstream Joint target prompt."""
from llm_x.data import _array_text

PPO_PRIOR = (
    'The trajectories shown below were generated by the same reinforcement-learning policy '
    'trained with Proximal Policy Optimization (PPO) to maximize expected cumulative reward. '
    "Use this fact as additional information when inferring the trained agent's action-selection behavior."
)

ICRFQI = """Before answering the next-action question, treat the supplied trajectories as an offline reinforcement-learning dataset and perform the following Fitted Q-Iteration style reasoning internally.

Each episode is an independent trajectory. Never create a transition across episode boundaries.

1. Reconstruct the transitions
   (s_t, a_t, r_t, s_{t+1})
   from every supplied episode.

2. Use the 10 action bins already defined in the question as the candidate action set.
   Map each observed continuous action a_t to its corresponding action bin.
   Define Q_k(s, b) as the estimated value of taking action-bin b at state s.

3. Initialize
   Q_0(s, b) = 0
   and use gamma = 0.99.

4. For k = 1, ..., K, with K = {K}, perform:

   y_t^(k) = r_t + gamma * max_b Q_(k-1)(s_(t+1), b)

   Then treat
   ((s_t, action_bin(a_t)), y_t^(k))
   as an in-context regression dataset.

   Infer Q_k(s, b) from these examples without updating model parameters.

   When an exact state-action-bin pair was not observed, estimate its value by regression/interpolation from the supplied examples rather than treating the unobserved action as impossible.

5. At the query state s_query, estimate
   Q_K(s_query, b)
   for all 10 action bins and select

   b* = argmax_b Q_K(s_query, b).

6. After selecting the action bin, estimate a real-valued action inside that bin using the observed continuous actions and policy behavior in the supplied trajectories.

Perform the iterative calculations internally. Do not print a large Q-table or all intermediate Bellman targets. In the visible answer, provide only the compact reasoning and the exact answer format required by the original next-action question."""

METHOD_K = {'direct': None, 'ppo_prior': None, 'icrfqi_k2': 2, 'icrfqi_k5': 5}


def reference_prefix(episodes, *, start, H):
    if not episodes:
        return ''
    blocks = [
        'Additional reference episodes generated by the same trained agent\n\n'
        'Each episode is an independent trajectory. Step indices restart in each episode. '
        'Never create a transition across episode boundaries.'
    ]
    for i, episode in enumerate(episodes, 1):
        end = start + H
        if episode.length <= end:
            raise ValueError(f'Missing state at step {end}: {episode.path}')
        blocks.append(
            f'[Additional reference episode {i}]\n'
            + episode.history_text(start, end, indexed=True)
            + f'\n\nState at step {end}: {_array_text(episode.state(end))}\n'
            + f'[End additional reference episode {i}]'
        )
    return '\n\n'.join(blocks) + '\n\n[Target episode]\n'


def compose_user(target_user, references, method):
    # Prepending preserves every byte of the original history, question and answer format.
    K = METHOD_K[method]
    instruction = PPO_PRIOR if method == 'ppo_prior' else (
        ICRFQI.replace('{K}', str(K)) if K is not None else ''
    )
    return (instruction + '\n\n' if instruction else '') + references + target_user
